const byId = new Map(expandedSkills.map((item) => [item.id, item]));
export function getExpandedSkill(id: string) { return byId.get(id); }
export function isExpandedSkill(id: string) { return byId.has(id); }
export function expandedSkillText(skill: ExpandedSkill, locale: Locale) { return { misconception: skill.misconception[locale], principle: skill.principle[locale], boundary: skill.boundary[locale], diagnosticScenario: skill.diagnosticScenario[locale], applicationScenario: skill.applicationScenario[locale], counterfactual: skill.counterfactual[locale], transferScenario: skill.transferScenario[locale], transferCorrect: skill.transferCorrect[locale] }; }
